<?php
declare(strict_types=1);
require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; require_once __DIR__.'/../shared/auth.php';
methodOnly('PUT'); requireAdmin();
safeApi(function():void{$db=apiDatabase();$id=requestId();$i=jsonRequest();$q=$db->prepare('SELECT id FROM coupons WHERE id=:id');$q->execute([':id'=>$id]);if(!$q->fetch())jsonResponse(false,'Coupon not found.',null,[],404);$code=strtoupper(trim((string)($i['code']??'')));$type=strtoupper((string)($i['discount_type']??''));$applies=strtoupper((string)($i['applies_to']??'ALL'));$value=(float)($i['discount_value']??0);if($code===''||inputString($i,'title',true)===''||!in_array($type,['PERCENTAGE','FIXED'],true)||$value<=0||($type==='PERCENTAGE'&&$value>100)||!in_array($applies,['ALL','PRODUCTS','CATEGORIES'],true))jsonResponse(false,'Invalid coupon details.',null,[],422);$d=$db->prepare('SELECT id FROM coupons WHERE code=:code AND id<>:id');$d->execute([':code'=>$code,':id'=>$id]);if($d->fetch())jsonResponse(false,'A coupon with this code already exists.',null,[],409);$db->beginTransaction();try{$u=$db->prepare('UPDATE coupons SET code=:code,title=:title,description=:description,discount_type=:type,discount_value=:value,min_order_amount=:min,max_discount=:max,start_date=:start,expiry_date=:expiry,usage_limit=:usage,per_user_limit=:peruser,status=:status,applies_to=:applies WHERE id=:id');$u->execute([':code'=>$code,':title'=>inputString($i,'title',true),':description'=>inputString($i,'description'),':type'=>$type,':value'=>$value,':min'=>(float)($i['min_order_amount']??0),':max'=>$i['max_discount']??null,':start'=>$i['start_date']??null,':expiry'=>$i['expiry_date']??null,':usage'=>(int)($i['usage_limit']??0),':peruser'=>(int)($i['per_user_limit']??0),':status'=>strtoupper((string)($i['status']??'ACTIVE')),':applies'=>$applies,':id'=>$id]);$db->prepare('DELETE FROM coupon_products WHERE coupon_id=:id')->execute([':id'=>$id]);$db->prepare('DELETE FROM coupon_categories WHERE coupon_id=:id')->execute([':id'=>$id]);foreach($applies==='PRODUCTS'?($i['product_ids']??[]):[] as $pid)$db->prepare('INSERT INTO coupon_products(coupon_id,product_id) VALUES(:c,:p)')->execute([':c'=>$id,':p'=>(int)$pid]);foreach($applies==='CATEGORIES'?($i['category_ids']??[]):[] as $cid)$db->prepare('INSERT INTO coupon_categories(coupon_id,category_id) VALUES(:c,:p)')->execute([':c'=>$id,':p'=>(int)$cid]);$db->commit();jsonResponse(true,'Coupon updated successfully.');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}});
